MagickExport MagickBooleanType IsBlobSeekable(const Image *image) /* <=== IsBlobSeekable */ 
{
  MagickBooleanType
    seekable;

  assert(image != (const Image *) NULL);
  assert(image->signature == MagickCoreSignature);
  if (image->debug != MagickFalse)
    (void) LogMagickEvent(TraceEvent,GetMagickModule(),"%s",image->filename);
  switch (image->blob->type)
  {
    case FileStream:
    case BlobStream:
    case ZipStream:
    {
      seekable=MagickTrue;
      break;
    }
    case UndefinedStream:
    case StandardStream:
    case BZipStream:
    case FifoStream:
    case PipeStream:
    default:
    {
      seekable=MagickFalse;
      break;
    }
    case CustomStream:
    {
      if ((image->blob->custom_stream->seeker != (CustomStreamSeeker) NULL) &&
          (image->blob->custom_stream->teller != (CustomStreamTeller) NULL))
        seekable=MagickTrue;
      else
        seekable=MagickFalse;
      break;
    }
  }
  return(seekable);
}

